def transform(grid):
    import collections
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, multicolour=True)
    singles = [o for o in objs if o["size"] == 1]
    shapes = [o for o in objs if o["size"] > 1]
    out = g.copy()
    moves = []
    for s in shapes:
        cols = collections.Counter(int(g[y, x]) for y, x in s["cells"])
        if len(cols) < 2:
            continue
        body = cols.most_common()[0][0]
        marker = cols.most_common()[-1][0]
        bodyset = {(y, x) for y, x in s["cells"] if g[y, x] == body}
        corner = None
        for (y, x) in sorted(bodyset):
            h = (y, x - 1) in bodyset or (y, x + 1) in bodyset
            v = (y - 1, x) in bodyset or (y + 1, x) in bodyset
            if h and v:
                corner = (y, x)
                break
        if corner is None:
            continue
        target = None
        for p in singles:
            py, px = p["cells"][0]
            if g[py, px] == marker:
                target = (py, px)
                break
        if target is None:
            continue
        moves.append((s, corner, target))
    for s, corner, target in moves:
        for y, x in s["cells"]:
            out[y, x] = bg
        out[target] = bg
    if moves:
        emit(out.copy(), "Erase each shape whose marker colour matches a lone pixel, along with that lone pixel.")
    for s, corner, target in moves:
        dy, dx = target[0] - corner[0], target[1] - corner[1]
        for y, x in s["cells"]:
            ny, nx = y + dy, x + dx
            if 0 <= ny < out.shape[0] and 0 <= nx < out.shape[1]:
                out[ny, nx] = g[y, x]
        emit(out.copy(), f"Redraw the shape with its L-corner on the lone pixel at {target}.")
    emit(out.copy(), "Final grid.")
    return out
